import React, { useState, useEffect } from 'react';
import EnhancedDraggableWidget from '../EnhancedDraggableWidget';
import './CalculatorWidget.css';

const CalculatorWidget = ({ onClose, isVisible = true }) => {
  const [input, setInput] = useState('');
  const [result, setResult] = useState('0');
  const [lastAnswer, setLastAnswer] = useState('0');
  const [angleMode, setAngleMode] = useState('deg'); // 'deg' or 'rad'
  const [activeTab, setActiveTab] = useState('main'); // 'main' or 'func'

  // --- Calculator Logic ---
  const appendToInput = (value) => {
    // If result is non-zero and we start typing an operator, append to result
    if (result !== '0' && result !== 'Error' && input === '' && ['+', '-', '*', '/', '^'].includes(value)) {
      setInput(result + value);
      return;
    }
    // If we just calculated and type a number, start fresh (default behavior)
    // If we want to chain, we can do that logic here, but simpler is clearer.
    setInput((prev) => prev + value);
  };

  const clearAll = () => {
    setInput('');
    setResult('0');
    setLastAnswer('0');
  };

  const backspace = () => {
    setInput((prev) => prev.slice(0, -1));
  };

  // Advanced calculation function
  const calculate = () => {
    if (!input.trim()) return;

    try {
      // Pre-process the input string to standard JS math
      let expression = input
        .replace(/×/g, '*')
        .replace(/÷/g, '/')
        .replace(/\^/g, '**')
        .replace(/π/g, 'Math.PI')
        .replace(/e/g, 'Math.E')
        .replace(/sqrt\(/g, 'Math.sqrt(')
        .replace(/log\(/g, 'Math.log10(') // Base 10 log usually implied on calcs
        .replace(/ln\(/g, 'Math.log(');   // Natural log

      // Handle Trigonometry based on Angle Mode
      // We wrap the argument in a conversion factor if in Degrees
      if (angleMode === 'deg') {
        const toRad = '(Math.PI/180)*';
        // Regex to insert conversion inside the parenthesis of trig functions
        // Checks for sin(, cos(, tan(
        expression = expression
          .replace(/sin\(/g, `Math.sin(${toRad}`)
          .replace(/cos\(/g, `Math.cos(${toRad}`)
          .replace(/tan\(/g, `Math.tan(${toRad}`);
      } else {
        // Radians is default JS behavior
        expression = expression
          .replace(/sin\(/g, 'Math.sin(')
          .replace(/cos\(/g, 'Math.cos(')
          .replace(/tan\(/g, 'Math.tan(');
      }

      // Percentage calculation: N% -> N/100
      // Basic implementation for "number%" -> "number/100"
      expression = expression.replace(/(\d+(\.\d+)?)%/g, '($1/100)');

      // Evaluate
      // eslint-disable-next-line no-eval
      const evalResult = eval(expression);

      if (isNaN(evalResult) || !isFinite(evalResult)) {
        throw new Error('Invalid calculation');
      }

      // Format: Precision to avoid floating point errors (0.1+0.2), limited to 12 digits
      const formattedResult = parseFloat(evalResult.toPrecision(12)).toString();
      setResult(formattedResult);
      setLastAnswer(formattedResult);
      // Optional: Clear input or set input to result?
      // Keeping input visible allows user to see what they typed.
      // Reset input for next fresh start?
      setInput('');
    } catch (error) {
      setResult('Error');
      console.error(error);
    }
  };

  // Keyboard Event Listener
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (!isVisible) return;
      const key = e.key;

      if (/[0-9]/.test(key)) appendToInput(key);
      if (['+', '-', '*', '/', '.', '(', ')'].includes(key)) appendToInput(key);
      if (key === 'Enter') calculate();
      if (key === 'Backspace') backspace();
      if (key === 'Escape') clearAll();
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [input, isVisible, angleMode]); // Re-bind if dependencies change logic (though append uses ref-like state or functional updates)


  if (!isVisible) return null;

  return (
    <EnhancedDraggableWidget
      id="calculator"
      className="calculator-widget"
      title="NOVA CALCULATOR"
      initialSize={{ width: 400, height: 550 }}
      minSize={{ width: 320, height: 450 }}
      onClose={onClose}
      isVisible={isVisible}
    >
      <div className="calculator-wrapper">

        {/* Header */}
        <div className="calculator-label">
          NOVA CALCULATOR
        </div>

        {/* Display Screen */}
        <div className="calculator-screen-area">
          <div className="calculator-input">{input || (result !== '0' && result !== 'Error' ? 'Ans = ' + result : '')}</div>
          <div className="calculator-result">{result === 'Error' ? 'Error' : (input ? (result !== '0' ? result : '') : result)}</div>
        </div>

        {/* Tab Controls */}
        <div className="controls-section">
          <div className="calculator-tabs">
            <button
              className={`tab-button ${activeTab === 'main' ? 'active' : ''}`}
              onClick={(e) => { e.stopPropagation(); setActiveTab('main'); }}
            >
              Main
            </button>
            <button
              className={`tab-button ${activeTab === 'abc' ? 'active' : ''}`} // Placeholder for future ABC tab logic if needed, mapped to Sci for now or separate?
              onClick={(e) => { e.stopPropagation(); setActiveTab('abc'); }} // Image shows ABC, implementing as placeholder or mapped to Sci
            >
              ABC
            </button>
            <button
              className={`tab-button ${activeTab === 'func' ? 'active' : ''}`}
              onClick={(e) => { e.stopPropagation(); setActiveTab('func'); }}
            >
              Func
            </button>
          </div>

          <div className="angle-mode">
            <button
              className={`angle-button ${angleMode === 'deg' ? 'active' : ''}`}
              onClick={(e) => { e.stopPropagation(); setAngleMode('deg'); }}
            >
              DEG
            </button>
            <button
              className={`angle-button ${angleMode === 'rad' ? 'active' : ''}`}
              onClick={(e) => { e.stopPropagation(); setAngleMode('rad'); }}
            >
              RAD
            </button>
          </div>
        </div>

        {/* Button Grid Content */}
        <div className="button-section">
          {activeTab === 'main' ? (
            <div className="calculator-buttons">
              {/* Row 1 */}
              <button className="calc-btn clear no-drag" onClick={clearAll}>C</button>
              <button className="calc-btn backspace no-drag" onClick={backspace}>⌫</button>
              <button className="calc-btn operator no-drag" onClick={() => appendToInput('/')}>/</button>
              <button className="calc-btn operator no-drag" onClick={() => appendToInput('*')}>×</button>

              {/* Row 2 */}
              <button className="calc-btn no-drag" onClick={() => appendToInput('7')}>7</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('8')}>8</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('9')}>9</button>
              <button className="calc-btn operator no-drag" onClick={() => appendToInput('-')}>-</button>

              {/* Row 3 */}
              <button className="calc-btn no-drag" onClick={() => appendToInput('4')}>4</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('5')}>5</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('6')}>6</button>
              <button className="calc-btn operator no-drag" onClick={() => appendToInput('+')}>+</button>

              {/* Row 4 */}
              <button className="calc-btn no-drag" onClick={() => appendToInput('1')}>1</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('2')}>2</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('3')}>3</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('(')}>(</button>

              {/* Row 5 */}
              <button className="calc-btn zero no-drag" onClick={() => appendToInput('0')}>0</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('.')}>.</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput(')')}>)</button>
              <button className="calc-btn scientific no-drag" onClick={() => appendToInput('sin(')}>sin</button>

              {/* Row 6: Full Width Equals */}
              <button
                className="calc-btn equals no-drag"
                onClick={calculate}
              >
                =
              </button>
            </div>
          ) : activeTab === 'abc' ? (
            <div className="calculator-buttons">
              {/* Letter buttons A-J */}
              <button className="calc-btn no-drag" onClick={() => appendToInput('A')}>A</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('B')}>B</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('C')}>C</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('D')}>D</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('E')}>E</button>

              <button className="calc-btn no-drag" onClick={() => appendToInput('F')}>F</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('G')}>G</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('H')}>H</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('I')}>I</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('J')}>J</button>

              <button className="calc-btn no-drag" onClick={() => appendToInput('K')}>K</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('L')}>L</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('M')}>M</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('N')}>N</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('O')}>O</button>

              <button className="calc-btn no-drag" onClick={() => appendToInput('P')}>P</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('Q')}>Q</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('R')}>R</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('S')}>S</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('T')}>T</button>

              <button className="calc-btn no-drag" onClick={() => appendToInput('U')}>U</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('V')}>V</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('W')}>W</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('X')}>X</button>
              <button className="calc-btn no-drag" onClick={() => appendToInput('Y')}>Y</button>

              <button className="calc-btn no-drag" onClick={() => appendToInput('Z')}>Z</button>
              <button className="calc-btn clear no-drag" onClick={clearAll}>C</button>
              <button className="calc-btn backspace no-drag" onClick={backspace}>⌫</button>
              <button className="calc-btn equals no-drag" onClick={calculate}>=</button>
              <button className="calc-btn ans no-drag" onClick={() => appendToInput(lastAnswer.toString())}>ANS</button>
            </div>
          ) : (
            // Function / Scientific Tab
            <div className="calculator-buttons scientific-grid">
              <button className="calc-btn scientific no-drag" onClick={() => appendToInput('Math.log(')}>log</button>
              <button className="calc-btn scientific no-drag" onClick={() => appendToInput('Math.log10(')}>log10</button>
              <button className="calc-btn scientific no-drag" onClick={() => appendToInput('Math.exp(')}>e^x</button>
              <button className="calc-btn scientific no-drag" onClick={() => appendToInput('Math.PI')}>π</button>

              <button className="calc-btn scientific no-drag" onClick={() => appendToInput('Math.asin(')}>asin</button>
              <button className="calc-btn scientific no-drag" onClick={() => appendToInput('Math.acos(')}>acos</button>
              <button className="calc-btn scientific no-drag" onClick={() => appendToInput('Math.atan(')}>atan</button>
              <button className="calc-btn scientific no-drag" onClick={() => appendToInput('Math.E')}>e</button>

              <button className="calc-btn scientific no-drag" onClick={() => appendToInput('Math.abs(')}>abs</button>
              <button className="calc-btn scientific no-drag" onClick={() => appendToInput('Math.floor(')}>floor</button>
              <button className="calc-btn scientific no-drag" onClick={() => appendToInput('Math.ceil(')}>ceil</button>
              <button className="calc-btn scientific no-drag" onClick={() => appendToInput('Math.round(')}>round</button>

              <button className="calc-btn scientific no-drag" onClick={() => appendToInput('Math.random()')}>rand</button>
              <button className="calc-btn scientific no-drag" onClick={() => appendToInput('!')}>!</button>
              <button className="calc-btn clear no-drag" onClick={clearAll}>C</button>
              <button className="calc-btn equals no-drag" onClick={calculate}>=</button>
            </div>
          )}
        </div>
      </div>
    </EnhancedDraggableWidget>
  );
};

export default CalculatorWidget;
